package com.medipanda.controller;
import com.medipanda.model.*; import com.medipanda.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/invoices") public class InvoiceController { private final OrderRepository orders; private final UserRepository users; public InvoiceController(OrderRepository o,UserRepository u){orders=o;users=u;}
 @GetMapping(value="/{id}",produces=MediaType.TEXT_HTML_VALUE) public String invoice(@PathVariable String id,Principal p){Order o=orders.findById(id).orElseThrow();User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();if(!"ADMIN".equals(u.getRole())&&!p.getName().equalsIgnoreCase(o.getCustomerEmail()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Forbidden");double total=o.getTotal()+o.getDeliveryFee();StringBuilder items=new StringBuilder();for(String x:o.getItems()==null?List.<String>of():o.getItems())items.append("<tr><td>").append(esc(x)).append("</td><td>1</td></tr>");return "<!doctype html><html><head><meta charset='UTF-8'><title>MediPanda Invoice</title><style>body{font-family:Arial;padding:40px;color:#17352a}main{max-width:720px;margin:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{font-size:22px;font-weight:bold;text-align:right;margin-top:20px}</style></head><body><main><h1>✚ MediPanda</h1><p>Invoice #"+esc(id.substring(Math.max(0,id.length()-8)))+"</p><p>Customer: "+esc(o.getCustomerName())+"<br>Delivery: "+esc(o.getDeliveryAddress())+"</p><table><tr><th>Medicine</th><th>Qty</th></tr>"+items+"</table><p>Subtotal: ৳"+o.getTotal()+"</p><p>Delivery: ৳"+o.getDeliveryFee()+"</p><p class='total'>Total: ৳"+total+"</p><p>Payment: "+esc(o.getPaymentMethod())+" · "+esc(o.getPaymentStatus())+"</p><script>window.print()</script></main></body></html>";}
 private String esc(String x){return String.valueOf(x==null?"":x).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
